class Solution {
public:
    int primePalindrome(int n) {
        if (n <= 2) return 2;
        if (n <= 3) return 3;
        if (n <= 5) return 5;
        if (n <= 7) return 7;
        if (n <= 11) return 11;

        for (int root = 1; ; root++) {
            long long p = makePalindrome(root);
            if (p >= n && isPrime(p)) return (int)p;
        }
    }

private:
    long long makePalindrome(int root) {
        long long p = root;
        int x = root / 10;
        while (x > 0) {
            p = p * 10 + x % 10;
            x /= 10;
        }
        return p;
    }

    bool isPrime(long long x) {
        if (x < 2) return false;
        if (x < 4) return true;
        if (x % 2 == 0) return false;
        for (long long i = 3; i * i <= x; i += 2) {
            if (x % i == 0) return false;
        }
        return true;
    }
};
